    if (cur.size() == a.length) { result.add(new ArrayList<>(cur)); return; }
    for (int i = 0; i < a.length; i++) {
        if (used[i]) continue;
        used[i] = true;  cur.add(a[i]);
        dfs(cur, used);
        cur.remove(cur.size() - 1);  used[i] = false;     // both undone
    }
}

